                if line.startswith(\"Uid:\"):
                    row[\"uid\"] = [int(x) for x in line.split()[1:5]]
                    break
        except Exception as exc:
            row[\"read_errors\"].append(\"status:\" + type(exc).__name__)
        try:
            row[\"name\"] = open(base + \"/comm\", \"r\", encoding=\"utf-8\", errors=\"replace\").read().rstrip(\"\n\")
        except Exception as exc:
            row[\"read_errors\"].append(\"comm:\" + type(exc).__name__)
        try:
            row[\"exe\"] = os.readlink(base + \"/exe\")
        except Exception as exc:
            row[\"read_errors\"].append(\"exe:\" + type(exc).__name__)
        rows.append(row)
    by_pid = {r[\"pid\"]: r for r in rows}
    for row in rows:
        row[\"children\"] = sorted(r[\"pid\"] for r in rows if r[\"ppid\"] == row[\"pid\"])
    candidates = [r[\"pid\"] for r in rows if (r[\"name\"] or \"\").lower().startswith(\"python\") or os.path.basename(r[\"exe\"] or \"\").lower().startswith(\"python\")]
    result = {\"schema\": \"s2-4d-linux-process-inventory-v1\", \"boot_id\": boot_id, \"boot_time_epoch\": boot_time, \"clock_ticks_per_second\": hz, \"observed_utc\": datetime.datetime.now(datetime.timezone.utc).isoformat(), \"process_count\": len(rows), \"python_candidates\": candidates, \"processes\": rows, \"cmdline_read\": False, \"environ_read\": False, \"truncated\": False}
    encoded = json.dumps(result, separators=(\",\", \":\"), ensure_ascii=True)
    if len(encoded.encode(\"utf-8\")) > MAX_BYTES:
        compact = {\"schema\": result[\"schema\"], \"boot_id\": boot_id, \"observed_utc\": result[\"observed_utc\"], \"process_count\": len(rows), \"python_candidates\": candidates, \"truncated\": True, \"truncation_reason\": \"inventory exceeds 4,000,000 UTF-8 bytes\", \"cmdline_read\": False, \"environ_read\": False}
        encoded = json.dumps(compact, separators=(\",\", \":\"), ensure_ascii=True)
    sys.stdout.write(encoded + \"\n\")
except Exception as exc:
    sys.stderr.write(json.dumps({\"error\": type(exc).__name__, \"message\": str(exc)}, separators=(\",\", \":\")) + \"\n\")
    raise SystemExit(2)
